struct User { name: String, level: u8 }
impl Drop for User { fn drop(&mut self) {} }

let user = User { name: "Ada".into(), level: 7 };
let name = user.name;

#[derive(Debug)]
struct User { name: String, level: u8 }

let user = User { name: "Ada".into(), level: 7 };
let name = user.name;
println!("{}", user.level);
let again = User { name, level: user.level };
